/** 返回 undefined = 本次没判定。 */
export type MemoryJudge = (request: MemoryJudgeRequest) => Promise<MemoryJudgeVerdict | undefined>

/** 没自动合并，但附近有很像的一条。 */
export interface MemorySuspect {
