      "path": "lib/index.js",
      "content": "// DPH 任务看板 —— 宿主侧插件。
// 职责：接收浏览器看板快照（POST /api/dph/taskboard），原子落盘到
// ~/.dsh/storages/taskboard.json，供 Agent（模型）用 fs 工具读取分析。
import { mkdirSync, readFileSync, renameSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { resolveDshHome } from "@deepseek-ai/dsh-home-paths";

/** 所需宿主服务：webServer（路由注册）。 */
const inject = ["webServer", "workspaceRegistry"];

/** 落盘目标：~/.dsh/storages/taskboard.json */
function storagePath() {
	return join(resolveDshHome(), "storages", "taskboard.json");
}

/** 校验快照：至少是 JSON 对象（会话化版本无 cards，仅需对象即可）。 */
function validateSnapshot(body) {
	const parsed = JSON.parse(body);
	if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
		throw new Error("快照必须是 JSON 对象");
	}
	return parsed;
}

/** 原子落盘：先写临时文件再 rename，避免半截文件。 */
function writeAtomic(snapshot, tmpName = "taskboard.json.tmp", target = storagePath()) {
	const dir = join(resolveDshHome(), "storages");
	const tmp = join(dir, tmpName);
	mkdirSync(dir, { recursive: true });
	writeFileSync(tmp, JSON.stringify(snapshot, null, 2));
	renameSync(tmp, target);
	return target;
}

function apply(ctx) {
	const webServer = ctx.webServer;
	if (!webServer || typeof webServer.register !== "function") {
		ctx.logger.warn("[dph-taskboard] webServer 服务不可用，落盘路由未注册");
		return;
	}
	const handler = async (req, res) => {
		try {
			if (req.method !== "POST") {
				res.writeHead(405, { "Content-Type": "application/json" });
				res.end(JSON.stringify({ ok: false, error: "method not allowed" }));
				return;
			}
			const chunks = [];
			for await (const chunk of req) chunks.push(chunk);
			const body = Buffer.concat(chunks).toString("utf8");
			if (body.length > 4 * 1024 * 1024) throw new Error("快照过大");
			const snapshot = validateSnapshot(body);
			const target = writeAtomic(snapshot);
			res.writeHead(200, { "Content-Type": "application/json" });
			res.end(JSON.stringify({
				ok: true,
				writtenAt: Date.now(),
				path: target,
				sessionCols: snapshot.sessionCols && typeof snapshot.sessionCols === "object" ? Object.keys(snapshot.sessionCols).length : 0,
				sessionMeta: snapshot.sessionMeta && typeof snapshot.sessionMeta === "object" ? Object.keys(snapshot.sessionMeta).length : 0
			}));
		} catch (err) {
			// 客户端数据问题（JSON 解析/快照过大）→ 400；服务器问题（写盘失败等）→ 500
			const clientError = err instanceof SyntaxError || (err instanceof Error && err.message === "快照过大");
			res.writeHead(clientError ? 400 : 500, { "Content-Type": "application/json" });
			res.end(JSON.stringify({ ok: false, error: err instanceof Error ? err.message : String(err) }));
		}
	};
	// 恢复（撤销归档）会话：harness 无 unarchive API。
	// 优先通过 workspaceRegistry 服务的内存态更新（内存 + 文件同步，刷新即生效）；
	// 服务不可用时 fallback 直接改归档存储文件（需重启 harness 生效）。
	const unarchiveHandler = async (req, res) => {
		const fail = (code, msg) => {
			res.writeHead(code, { "Content-Type": "application/json" });
			res.end(JSON.stringify({ ok: false, error: msg }));
		};
		const respond = (archivedLeft, requiresRestart) => {
			res.writeHead(200, { "Content-Type": "application/json" });
			res.end(JSON.stringify({ ok: true, sessionId, requiresRestart, archivedLeft }));
		};
		let sessionId;
		try {
			if (req.method !== "POST") return fail(405, "method not allowed");
			const chunks = [];
			for await (const chunk of req) chunks.push(chunk);
			const body = Buffer.concat(chunks).toString("utf8");
			const parsed = JSON.parse(body);
			sessionId = parsed && typeof parsed.sessionId === "string" ? parsed.sessionId : "";
			if (!sessionId) return fail(400, "缺少 sessionId");
			// 格式校验：harness 会话 id 形如 session-<hex> / od-<hex>；拒绝垃圾 id，避免污染归档集合
			if (!/^(session|od)-[0-9a-f]+$/i.test(sessionId)) return fail(400, "非法的 sessionId：" + sessionId);
		} catch (err) {
			return fail(400, err instanceof Error ? err.message : String(err));
		}
		// 方案 A：workspaceRegistry 服务内存态更新（无重启）
		const registry = ctx.workspaceRegistry;
		if (registry && typeof registry.enqueueOperation === "function" && typeof registry.requireState === "function" && typeof registry.setState === "function") {
			try {
				await registry.enqueueOperation(async () => {
					const state = registry.requireState();
					const list = state && Array.isArray(state.archivedSessionIds) ? state.archivedSessionIds : null;
					if (list === null) throw new Error("workspace 状态缺少 archivedSessionIds");
					if (!list.includes(sessionId)) throw Object.assign(new Error("该会话不在归档列表"), { code: 404 });
					const next = { ...state, archivedSessionIds: list.filter((id) => id !== sessionId) };
					await registry.setState(next);
					respond(next.archivedSessionIds.length, false);
				});
				return;
			} catch (err) {
				if (err && err.code === 404) return fail(404, err.message);
				// registry 存在但操作失败：直接失败返回，绝不回退文件方案——
				// 否则 registry 后续 setState 会用仍含该 id 的内存态覆盖本次恢复，造成静默回退
				ctx.logger.warn("[dph-taskboard] 内存态恢复失败：" + (err instanceof Error ? err.message : String(err)));
				return fail(500, "恢复失败：" + (err instanceof Error ? err.message : String(err)));
			}
		}
		// 方案 B（仅当 registry 服务完全缺失时）：直接改归档存储文件（需重启）
		try {
			const file = join(resolveDshHome(), "storages", "workspace.json");
			const raw = readFileSync(file, "utf8");
			const state = JSON.parse(raw);
			const list = state && state.global && Array.isArray(state.global.archivedSessionIds) ? state.global.archivedSessionIds : null;
			if (list === null) return fail(400, "workspace.json 缺少 global.archivedSessionIds");
			if (!list.includes(sessionId)) return fail(404, "该会话不在归档列表");
			state.global.archivedSessionIds = list.filter((id) => id !== sessionId);
			writeAtomic(state, "workspace.json.tmp", file);
			respond(state.global.archivedSessionIds.length, true);
		} catch (err) {
			fail(400, err instanceof Error ? err.message : String(err));
		}
	};
	const disposeUnarchive = webServer.register({ kind: "exact", path: "/api/dph/taskboard/unarchive", handler: unarchiveHandler });
	ctx.on("dispose", disposeUnarchive);
	const dispose = webServer.register({ kind: "exact", path: "/api/dph/taskboard", handler });
	ctx.on("dispose", dispose);
